import zlib from 'node:zlib';
const input = Buffer.from('hello hello hello hello');
function roundTrip(next: () => void): void { zlib.gzip(input, (error: any, packed: Buffer) => { const first = error === null; zlib.gunzip(packed, (error2: any, plain: Buffer) => { console.log(first, error2 === null, plain.toString()); next(); }); }); }
function invalid(next: () => void): void { zlib.gunzip(Buffer.from('not gzip data'), (error3: any, none: any) => { console.log(error3.code, none === undefined); next(); }); }
function withOptions(next: () => void): void { zlib.deflate(input, { level: 9 }, (error4: any, deflated: Buffer) => { const ok = error4 === null; zlib.inflate(deflated, (error5: any, inflated: Buffer) => { console.log(ok, error5 === null, inflated.toString() === 'hello hello hello hello'); next(); }); }); }
function main(): void { roundTrip(() => { invalid(() => { withOptions(() => { console.log('done'); }); }); }); }

import net from 'node:net'; import zlib from 'node:zlib';
function main(): void {
  const server = net.createServer((_socket: any) => {});
  server.listen(0, '127.0.0.1', () => {
    const port = (server.address() as any).port;
    const client = net.connect({ host: '127.0.0.1', port });
    client.on('error', () => {});
    let ticks = 0;
    const timer = setInterval(() => { ticks++; }, 2);
    const input = Buffer.alloc(4 * 1024 * 1024); input.fill(97);
    zlib.gzip(input, (e: any, packed: Buffer) => {
      const gzipOk = e === null;
      zlib.gunzip(packed, (e2: any, plain: Buffer) => {
        const gunzipOk = e2 === null;
        client.write('x', () => {
          console.log('zlib', gzipOk, gunzipOk, plain.length === input.length);
          console.log('timer ran during zlib', ticks > 0);
          console.log('connected', client.remotePort === port);
          clearInterval(timer); client.destroy(); server.close();
        });
      });
    });
  });
}

