  async find(xs: number[]): Promise<number> {
    for (const x of xs) { if (x > this.base) return x; }
    return -1;
  }
  async findAwait(xs: number[]): Promise<number> {
    for (const x of xs) { await tick(); if (x > this.base) return x; }
